('19', 'محضرات أساسها', '1905', '', '1905901000', 'البراشيم الفارغة  لمحضرات الصيدلة.', '', '', '', '[]'),
('19', 'محضرات أساسها', '1905', '', '1905909010', 'بسكويت آخر خلاف البسكويت الحلو،  وإن كان محتويا علي كاكاو .', '', '', '', '[]'),
