-- Egypt Customs Tariff Database Dump
-- Source: Nafeza (MTS) / Egyptian Customs Authority
-- Exported: 2026-10-03

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


CREATE TABLE IF NOT EXISTS `customs_tariff_chapters` (
    `chapter_code` VARCHAR(4) PRIMARY KEY,
    `chapter_name` VARCHAR(255) NOT NULL,
    `items_count` INT DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE IF NOT EXISTS `customs_tariff` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `chapter_code` VARCHAR(4) NOT NULL,
    `chapter_name` VARCHAR(255) NOT NULL,
    `heading_code` VARCHAR(8) NOT NULL,
    `heading_name` TEXT DEFAULT NULL,
    `item_code` VARCHAR(20) NOT NULL UNIQUE,
    `item_name` TEXT NOT NULL,
    `import_duty` TEXT DEFAULT NULL,
    `vat_rate` TEXT DEFAULT NULL,
    `other_taxes` TEXT DEFAULT NULL,
    `rules_json` LONGTEXT DEFAULT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX `idx_chapter` (`chapter_code`),
    INDEX `idx_heading` (`heading_code`),
    INDEX `idx_item_code` (`item_code`),
    FULLTEXT INDEX `idx_ft_item` (`item_code`, `item_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


ON DUPLICATE KEY UPDATE `item_name`=VALUES(`item_name`), `heading_name`=VALUES(`heading_name`), `import_duty`=VALUES(`import_duty`), `vat_rate`=VALUES(`vat_rate`), `other_taxes`=VALUES(`other_taxes`), `rules_json`=VALUES(`rules_json`);

